package ru.neverland.townycrime;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import ru.neverland.core.*;
import static ru.neverland.townycrime.CrimePatrols.*;
public final class CrimePatrolsSmoke {
    static int checks;static void check(boolean yes,String why){if(!yes)throw new AssertionError(why);checks++;}interface Work{void run()throws Exception;}static void reject(Work work,String why)throws Exception{try{work.run();}catch(Exception expected){check(true,why);return;}throw new AssertionError(why);}
    static UUID town=UUID.randomUUID(),worker=UUID.randomUUID(),issuer=UUID.randomUUID();
    static Patrol patrol(UUID id,UUID person){return new Patrol(id,town,"dock","Порт",person,"GuardPlayer",issuer,100,Phase.ASSIGNED,"",null,0,1);}
    public static void main(String[]args)throws Exception{
        var value=patrol(UUID.randomUUID(),worker);var state=State.empty().patrol(value);check(state.patrols().size()==1,"assigned snapshot");reject(()->state.patrol(patrol(UUID.randomUUID(),worker)),"no duplicate active assignment per citizen");
        var complete=value.finish(Phase.COMPLETED,worker,"Проверил причал, нарушений не заметил",150);var completed=state.patrol(complete);check(completed.patrols().get(value.id()).report().equals(complete.report())&&complete.revision()==2,"one bounded authored report");reject(()->completed.patrol(complete),"no repeated completed receipt");reject(()->state.patrol(value.finish(Phase.COMPLETED,worker,"",150)),"no empty attendance report");reject(()->state.patrol(value.finish(Phase.COMPLETED,worker,"abc\nbad",150)),"no control characters");reject(()->state.patrol(new Patrol(value.id(),town,"elsewhere","Другой",worker,"GuardPlayer",issuer,100,Phase.COMPLETED,"Changed place",worker,150,2)),"assignment district immutable");
        var reassigned=completed.patrol(patrol(UUID.randomUUID(),worker));check(reassigned.patrols().size()==2,"new assignment keeps previous report");var cancelled=state.patrol(value.finish(Phase.CANCELLED,issuer,"Район закрыт на реконструкцию",150));check(cancelled.patrols().get(value.id()).phase()==Phase.CANCELLED,"cancellation stored without sanctions");
        var planned=new CrimeState(town,75,1000,2000,new CrimeState.Incident(UUID.randomUUID(),"BURGLARY","wood",2500,"PLANNED",100,1000));check(Incident.confirmed(planned).isEmpty(),"planned intent never becomes evidence");check(Incident.confirmed(planned.incident(planned.incident().phase("SKIPPED"))).isEmpty(),"skipped theft never becomes evidence");var incident=Incident.confirmed(planned.incident(planned.incident().phase("APPLIED"))).orElseThrow();check(incident.equals(Incident.confirmed(planned.incident(planned.incident().phase("CLOSED"))).orElseThrow()),"closed recovery shares exact confirmed identity");var archived=completed.observe(List.of(incident));check(archived.observe(List.of(incident)).equals(archived),"incident recovery deduplicates");reject(()->archived.observe(List.of(new Incident(incident.id(),town,"BURGLARY","wood",2600,100))),"same evidence ID cannot change amount");check(incident.evidence().get("amount").equals(2500L)&&incident.evidence().get("sourceId").equals("crime:"+incident.id())&&!incident.evidence().containsKey("subject")&&!incident.evidence().containsKey("district"),"evidence preserves units and never invents suspect or place");
        Path folder=Files.createTempDirectory("crime-patrols-");Path file=folder.resolve("patrol-data.yml");var repo=new CrimePatrolRepository(file);repo.load();repo.commit(repo.state(),state).toCompletableFuture().get(5,TimeUnit.SECONDS);check(repo.state().equals(state),"confirmed snapshot published");
        var lockField=AtomicFiles.class.getDeclaredField("writers");lockField.setAccessible(true);@SuppressWarnings("unchecked")var locks=(Map<Path,ReentrantLock>)lockField.get(null);var lock=locks.computeIfAbsent(file.toAbsolutePath().normalize(),unused->new ReentrantLock());lock.lock();try{var future=repo.commit(state,archived).toCompletableFuture();Thread.sleep(50);check(repo.busy()&&!future.isDone()&&repo.state().equals(state),"pending file never publishes report or evidence");check(SuiteState.tryRun("crime optional file delayed",()->{}),"file wait never holds suite lock");reject(()->repo.commit(state,cancelled).toCompletableFuture().join(),"overlapping optional writes rejected");}finally{lock.unlock();}repo.prepareClose().toCompletableFuture().get(5,TimeUnit.SECONDS);repo.awaitClosed();check(repo.state().equals(archived),"shutdown drains exact accepted image");
        var restart=new CrimePatrolRepository(file);restart.load();check(restart.state().equals(archived),"reports and source evidence survive restart exactly");restart.awaitClosed();Path bad=folder.resolve("bad.yml");Files.writeString(bad,"schema: 99\npatrols: changed\n");var invalid=new CrimePatrolRepository(bad);reject(invalid::load,"unknown optional schema refused");check(!invalid.readable()&&!invalid.writable()&&Files.readString(bad).equals("schema: 99\npatrols: changed\n"),"invalid optional journal never overwritten");invalid.awaitClosed();
        Path blocked=folder.resolve("blocked.yml");var fail=new CrimePatrolRepository(blocked);fail.load();Files.createDirectory(blocked);Files.writeString(blocked.resolve("occupied"),"fixture");reject(()->fail.commit(fail.state(),state).toCompletableFuture().join(),"physical replacement failure acknowledged");check(fail.state().equals(State.empty())&&!fail.writable(),"failed write remains unpublished and closes new writes");try{fail.awaitClosed();}catch(RuntimeException expected){}
        System.out.println("CrimePatrolsSmoke PASS "+checks+" checks");
    }
}
